*{box-sizing:border-box} :root{--ink:#17201f;--muted:#75807d;--line:rgba(22,35,32,.12);--paper:#f6f7f6;--lime:#c8f05e;--red:#ed6b64;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}html,body{height:100%;margin:0;background:#f4f6f4;color:var(--ink);font-family:var(--sans);overflow:hidden}.game-shell{position:relative;width:100%;height:100dvh;min-height:560px;overflow:hidden;background:radial-gradient(ellipse at 50% 49%,#fff 0%,#f8f9f8 49%,#edf0ed 100%);isolation:isolate}#arena{position:absolute;inset:0;width:100%;height:100%;z-index:0}.grain{position:absolute;inset:0;pointer-events:none;z-index:1;opacity:.14;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.16'/%3E%3C/svg%3E")}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:86px;padding:0 4.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(37,49,46,.08)}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none;font-size:13px;font-weight:800;letter-spacing:.11em}.brand small{display:block;color:#8a9591;font:9px var(--mono);letter-spacing:.13em;margin-top:3px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#1a2623;color:var(--lime);font-weight:800;font-size:18px;letter-spacing:-.08em;box-shadow:0 4px 12px #17201f22}.session-pill{font:10px var(--mono);letter-spacing:.07em;color:#687470;background:#ffffffa8;border:1px solid var(--line);border-radius:24px;padding:11px 16px}.session-pill b{color:#27332f;font-weight:500}.live-dot,.status-pip{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a7d948;margin-right:8px;box-shadow:0 0 0 3px #a7d94824}.divider{padding:0 9px;color:#c4ccc7}.sound-button{width:37px;height:37px;background:#ffffffa6;border:1px solid var(--line);border-radius:50%;color:#52605b;cursor:pointer;font-size:19px;display:grid;place-content:center}.reset-label{display:none}.hud,.dummy-card{position:absolute;z-index:3;background:rgba(255,255,255,.82);border:1px solid rgba(37,49,46,.1);box-shadow:0 12px 35px rgba(34,48,42,.045);backdrop-filter:blur(14px);border-radius:12px}.hud{top:116px;right:4.1%;width:255px;padding:17px 18px 14px}.hud-heading{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);letter-spacing:.11em;color:#737f7a;padding-bottom:14px;border-bottom:1px solid #e9edeb;margin-bottom:14px}.hud-id{color:#adb5b1}.meter{margin:0 0 13px}.meter-title,.dummy-health-row{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:.05em;color:#697570;margin-bottom:7px}.meter-title strong,.dummy-health-row b{font:600 12px var(--mono);color:#293430;letter-spacing:0}.meter-title small,.dummy-health-row small{font-size:9px;color:#9aa39f;font-weight:400}.meter-title i{font-style:normal;font-size:12px;margin-right:5px}.icon-heart{color:#e77b73}.icon-stamina{color:#9abd44}.icon-food{color:#e4aa59}.track{height:6px;border-radius:8px;background:#e8ece9;overflow:hidden}.fill{height:100%;width:100%;border-radius:8px;transition:width .22s ease}.hp-fill{background:linear-gradient(90deg,#e77d72,#ec6a63)}.stamina-fill{background:linear-gradient(90deg,#acd748,#c8eb69)}.hunger-fill{background:linear-gradient(90deg,#e5af62,#f0cb7a)}.status-foot{border-top:1px solid #e9edeb;padding-top:12px;margin-top:2px;color:#858f8b;font:9px var(--mono);letter-spacing:.07em}.status-pip{width:5px;height:5px;background:#a5d44e;margin-right:6px}.dummy-card{top:135px;left:4.1%;width:260px;padding:16px 17px 14px}.dummy-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:17px}.eyebrow{font:9px var(--mono);letter-spacing:.12em;color:#87928d}.dummy-head h2{margin:5px 0 0;font-size:13px;letter-spacing:-.025em;font-weight:700}.dummy-level{font:8px var(--mono);color:#929c97;margin-left:4px}.dummy-icon{font-size:18px;color:#aab8a0;width:31px;height:31px;display:grid;place-items:center;border-radius:9px;background:#f0f3ed}.dummy-health-row{margin-bottom:7px}.dummy-track{height:5px}.dummy-fill{background:#9abd57}.dummy-state{margin-top:11px;font:8px var(--mono);letter-spacing:.06em;color:#84908a}.state-dot{display:inline-block;width:5px;height:5px;border-radius:50%;background:#a9d84c;margin:0 7px 1px 0}.arena-label{position:absolute;top:47%;left:50%;transform:translate(-50%,-50%);z-index:2;display:flex;align-items:center;gap:10px;color:#9ba49f;font:9px var(--mono);letter-spacing:.14em;pointer-events:none;white-space:nowrap}.arena-label .crosshair{font-size:15px;color:#c0c9c3}.arena-line{width:58px;height:1px;background:#dce1dd}.arena-label b{color:#76817b;font-weight:400}.tips-card{position:absolute;z-index:3;left:4.1%;bottom:123px;display:flex;align-items:center;gap:10px;padding:10px 13px;background:#ffffffaa;border:1px solid var(--line);border-radius:8px;color:#84908b;font-size:10px}.tips-card b{color:#45514b;font-weight:700}.tips-icon{font-size:19px;color:#9cc94c}.combo-toast{position:absolute;z-index:5;left:50%;top:38%;transform:translate(-50%,-50%) scale(.92);opacity:0;pointer-events:none;text-align:center;padding:13px 22px;background:#18231f;color:#fff;border-radius:8px;box-shadow:0 8px 26px #16231d44;transition:opacity .15s,transform .15s}.combo-toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.combo-toast span,.combo-toast small{display:block;font:8px var(--mono);letter-spacing:.17em;color:#b9d483}.combo-toast strong{display:block;font-size:22px;letter-spacing:.12em;margin:3px 0}.combo-toast small{color:#a7b0aa}.impact-label{position:absolute;z-index:5;left:50%;top:43%;transform:translate(-50%,-50%) scale(.8);font:800 14px var(--sans);letter-spacing:.14em;color:#dc665f;text-shadow:0 2px 10px #fff;opacity:0;pointer-events:none}.impact-label.show{animation:impact .55s ease-out}@keyframes impact{0%{opacity:0;transform:translate(-50%,-40%) scale(.7)}25%{opacity:1;transform:translate(-50%,-50%) scale(1.05)}100%{opacity:0;transform:translate(-50%,-65%) scale(1)}}.bottom-ui{position:absolute;z-index:3;bottom:40px;left:4.1%;right:4.1%;display:flex;align-items:flex-end;justify-content:space-between;gap:24px}.controls-legend{display:flex;align-items:center;gap:18px;color:#89938e;font:8px var(--mono);letter-spacing:.08em;padding-bottom:12px}.controls-legend>div{display:flex;align-items:center;gap:7px}.key-group{display:flex;gap:2px}.controls-legend kbd,.action-key{display:inline-grid;place-items:center;min-width:19px;height:20px;padding:0 4px;border:1px solid #d6ddd8;border-radius:4px;background:#ffffffa8;color:#606c66;font:9px var(--mono);box-shadow:0 1px 0 #dce1dd}.controls-legend>div>kbd{min-width:39px}.action-bar{display:flex;gap:9px}.action-button{position:relative;display:flex;align-items:center;gap:12px;width:188px;height:55px;padding:0 12px;background:#fff;border:1px solid rgba(41,54,49,.12);border-radius:8px;text-align:left;cursor:pointer;color:var(--ink);box-shadow:0 7px 16px #27342d0b;transition:transform .14s,box-shadow .14s,border .14s}.action-button:hover{transform:translateY(-2px);box-shadow:0 10px 20px #27342d16;border-color:#c5d4b0}.action-button:active{transform:translateY(1px)}.action-button.heavy{background:#202b27;color:white;border-color:#202b27}.action-key{width:30px;height:28px;font-size:10px;font-weight:500;background:#f5f7f4;border:0;color:#52605a}.heavy .action-key{background:#39443e;color:#d4e5ba}.action-copy b,.action-copy small{display:block;white-space:nowrap}.action-copy b{font-size:9px;letter-spacing:.08em}.action-copy small{margin-top:3px;color:#97a19c;font:8px var(--mono)}.heavy .action-copy small{color:#adb7b1}.action-arrow{margin-left:auto;color:#9fac9d;font-size:15px}.heavy .action-arrow{color:#c6e56d}.mouse-tip{align-self:center;display:flex;align-items:center;gap:8px;padding-bottom:10px;color:#8a9590;font:8px var(--mono);letter-spacing:.08em}.mouse-icon{font-size:17px;color:#8d9b91}.bottom-note{position:absolute;z-index:3;bottom:0;left:4.1%;right:4.1%;height:25px;border-top:1px solid rgba(38,51,46,.08);display:flex;align-items:center;justify-content:space-between;color:#a2aba6;font:8px var(--mono);letter-spacing:.1em}.bottom-note i{font-style:normal;color:#a6cf5a;margin:0 4px}.mobile-controls{display:none}.ko-overlay{position:absolute;inset:0;z-index:8;display:none;place-items:center;background:rgba(240,243,239,.58);backdrop-filter:blur(8px)}.ko-overlay.show{display:grid}.ko-card{max-width:380px;margin:20px;text-align:center;padding:34px;background:#fff;border:1px solid var(--line);border-radius:13px;box-shadow:0 18px 50px #26352c22}.ko-card h1{font-size:27px;letter-spacing:-.07em;margin:10px 0}.ko-card p{color:#77827c;font-size:12px;line-height:1.6}.ko-card button{margin-top:13px;padding:13px 17px;border:0;border-radius:6px;background:#202b27;color:#fff;font:10px var(--mono);letter-spacing:.1em;cursor:pointer}.ko-card button span{margin-left:20px;color:var(--lime)}
