ions button{height:36px;padding:0 10px;font-size:9px}.touch-actions #touchHeavy{background:#202b27;color:white;border-color:#202b27}.bottom-note{left:12px;right:12px;height:23px;font-size:6px}.bottom-note span:last-child{letter-spacing:.03em}.arena-label{display:none}}
