const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002');
  await page.locator('#resetBtn').click();
  await page.locator('#lightBtn').click();
  await page.waitForTimeout(70);
  await page.locator('#lightBtn').click();
  await page.waitForTimeout(70);
  await page.locator('#heavyBtn').click();
  await page.waitForTimeout(1250);
  const combo = await page.evaluate(() => ({
    hp: document.querySelector('#dummyHpText').innerText,
    toast: getComputedStyle(document.querySelector('#comboToast')).opacity,
    toastText: document.querySelector('#comboToast').innerText,
    hiddenDebug: !('__debugGame' in window)
  }));
  await page.screenshot({ path: '/tmp/opencode/roundhouse.jpg', type: 'jpeg', quality: 85 });
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(100);
  const mobile = await page.evaluate(() => ({
    viewport: [innerWidth, innerHeight],
    doc: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
    touchControls: getComputedStyle(document.querySelector('.mobile-controls')).display,
    health: document.querySelector('#hpText').innerText
  }));
  console.log(JSON.stringify({ combo, mobile, errors }, null, 2));
  await browser.close();
})();
