  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002');
  await page.locator('#resetBtn').click();
  await page.waitForFunction(() => document.querySelector('#dummyState').innerText.includes('ATTACKING'), null, { timeout: 5000 });
  await page.keyboard.press('Space');
  await page.waitForTimeout(360);
  const slipMessage = await page.locator('#impactLabel').innerText();
  const staminaAfterSlip = await page.locator('#staminaText').innerText();
  await page.locator('#heavyBtn').click();
  await page.waitForTimeout(550);
  const result = {
    slipMessage,
    staminaAfterSlip,
    dummyHpAfterHeavy: await page.locator('#dummyHpText').innerText(),
    impact: await page.locator('#impactLabel').innerText(),
    playerStatus: await page.locator('#statusText').innerText(),
    errors
  };
  console.log(JSON.stringify(result, null, 2));
  await browser.close();
})();
